#!/usr/bin/env python3
import sys
from datetime import datetime

def parse_date(date_str):
    """Try to parse the date string with common formats"""
    formats = [
        '%Y-%m-%d', '%Y/%m/%d', '%Y-%m-%d %H:%M:%S',
        '%d/%m/%Y', '%d-%m-%Y', '%m/%d/%Y', '%m-%d-%Y',
        '%Y%m%d', '%Y%m%d%H%M%S', '%d.%m.%Y', '%d.%m.%Y',
        '%Y.%m.%d', '%Y.%m.%d', '%d.%m.%Y', '%d.%m.%Y'
    ]

    for fmt in formats:
        try:
            return datetime.strptime(date_str, fmt)
        except ValueError:
            continue

    # Try to parse with a more flexible approach
    # Handle cases like 2023-5-1 (single digit month/day)
    try:
        # Replace single digit separators with double digits
        parts = date_str.split('-')
        if len(parts) == 3:
            year = parts[0]
            month = int(parts[1])
            day = int(parts[2])
            return datetime(int(year), month, day)
    except:
        pass

    raise ValueError(f"Unable to parse date: {date_str}")

def format_date(date, format_str):
    """Format the date according to the format string"""
    return date.strftime(format_str)

if __name__ == '__main__':
    if len(sys.argv) != 3:
        print("Usage: date-format <date> <format>")
        sys.exit(1)

    date_str = sys.argv[1]
    format_str = sys.argv[2]

    try:
        date = parse_date(date_str)
        result = format_date(date, format_str)
        print(result)
    except ValueError as e:
        print(f"Error: {e}", file=sys.stderr)
        sys.exit(1)
EOF
